exercises.solution:
class Rectangle:
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


class Square(Rectangle):
    def __init__(self, side):
        super().__init__(side, side)


def check(side):
    s = Square(side)
    return [s.area(), isinstance(s, Rectangle)]

import math


class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        raise NotImplementedError

    def describe(self):
        return f"{self.name} 넓이 {self.area():.2f}"


class Circle(Shape):
    def __init__(self, r):
        super().__init__("원")
        self.r = r

    def area(self):
        return math.pi * self.r ** 2


class Rect(Shape):
    def __init__(self, w, h):
        super().__init__("직사각형")
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


def report(specs):
    shapes = []
    for s in specs:
        shapes.append(Circle(s[1]) if s[0] == "circle" else Rect(s[1], s[2]))
    total = 0
    descriptions = []
    for shape in shapes:
        descriptions.append(shape.describe())
        total += shape.area()
    return [descriptions, round(total, 2)]
